// Graph events (Send Event / On Event), one game-global namespace:
// NearDoor, Checkpoint
// The arrays are the script API's (tyrax.hpp), so tyrax::sendEvent
// and an On Event node meet on the same bus.
static unsigned char* const flowEvtCur = tyrax::detail::g_evtCur;
static float* const flowEvtCurVal = tyrax::detail::g_evtCurVal;
static unsigned char* const flowEvtNext = tyrax::detail::g_evtNext;
static float* const flowEvtNextVal = tyrax::detail::g_evtNextVal;
static_assert(tyrax::EVENT_COUNT == 2, "tyrax/names.gen.hpp is stale");

// The bus. Registered before every graph script, so `cur` is
// already this frame's mail by the time any receiver looks.
class FlowEventBus : public Script {
 public:
  void update(ScriptContext& ctx) override {
    // Halted at a breakpoint: freeze the mail too, or an
    // event sent just before the stop would be dropped
    // while the author was looking at it.
    if (livedbg::halted()) return;
    if (ctx.sceneGeneration != generation_) {
      // A scene (re)load must not deliver the old scene's mail -
      // but a script's onStart may already have sent this scene's
      // (tyrax::sendEvent stamps the generation): that is kept for
      // the next frame.
      generation_ = ctx.sceneGeneration;
      for (int i = 0; i < 2; ++i) {
        flowEvtCur[i] = 0;
        flowEvtCurVal[i] = 0.0F;
        if (tyrax::detail::g_evtNextGen[i] != ctx.sceneGeneration) {
          flowEvtNext[i] = 0;
          flowEvtNextVal[i] = 0.0F;
        }
      }
      return;
    }
    for (int i = 0; i < 2; ++i) {
      flowEvtCur[i] = flowEvtNext[i];
      flowEvtCurVal[i] = flowEvtNextVal[i];
      flowEvtNext[i] = 0;
    }
  }

 private:
  unsigned int generation_ = 0;
};

// World Facts (docs/world-facts.md): the declared state of
// the game world. One float array for every scalar fact, one
// for positions; a computed fact has no slot because it IS a
// query. factWrite() is the only door in - it exists so the
// Live Debugger can record WHO changed a fact, and folds to a
// plain store when the debugger is off.
float factNum[1] = {0.0F};
float factPos[1][3] = {{0.0F, 0.0F, 0.0F}};

static inline void factWrite(int slot, float v, int src) {
  if (factNum[slot] != v) livedbg::factWrite(slot, v, src);
  factNum[slot] = v;
}
static inline void factWritePos(int slot, float x, float y,
                                float z, int src) {
  if (factPos[slot][0] != x || factPos[slot][1] != y ||
      factPos[slot][2] != z)
    livedbg::factWritePos(slot, x, y, z, src);
  factPos[slot][0] = x;
  factPos[slot][1] = y;
  factPos[slot][2] = z;
}
void factStore(int slot, float v) { factWrite(slot, v, -1000); }
void factStorePos(int slot, float x, float y, float z) {
  factWritePos(slot, x, y, z, -1000);
}

void factResetAll() {
  for (int i = 0; i < FACT_NUM_COUNT; ++i)
    factNum[i] = FACT_NUM_DEFAULT[i];
  for (int i = 0; i < FACT_POS_COUNT; ++i)
    for (int a = 0; a < 3; ++a)
      factPos[i][a] = FACT_POS_DEFAULT[i][a];
}

void factResetScene() {
  for (int i = 0; i < FACT_NUM_COUNT; ++i)
    if (FACT_NUM_SCENE[i]) factNum[i] = FACT_NUM_DEFAULT[i];
  for (int i = 0; i < FACT_POS_COUNT; ++i)
    if (FACT_POS_SCENE[i])
      for (int a = 0; a < 3; ++a)
        factPos[i][a] = FACT_POS_DEFAULT[i][a];
}

